// TestMain builds the CLI binary once before running all tests.
func TestMain(m *testing.M) {
	// Build binary once to a temp directory
	tmpDir, err := os.MkdirTemp("", "entire-integration-test-*")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to create temp dir for binary: %v\n", err)
		os.Exit(1)
	}

	testBinaryPath = filepath.Join(tmpDir, "entire")
	if runtime.GOOS == "windows" {
		testBinaryPath += ".exe"
	}

	// Route every spawned CLI away from the developer's real ~/.config/entire
	// (contexts.json, version_check.json), ~/.cache/entire (discovery caches),
	// and OS keychain. testing.Testing() is false in the subprocess, so the
	// internal/testdirs fallback cannot protect it — isolation must come from
	// the environment, which children inherit because all integration env
	// building starts from os.Environ() (testutil.GitIsolatedEnv).
	//
	// GIT_TERMINAL_PROMPT=0 and ENTIRE_TEST_GIT_HERMETIC form the hermeticity
	// tripwire: the latter makes GitIsolatedEnv's global git config route HTTPS
	// transport to real external hosts (github.com, gitlab.com) through a dead
	// loopback proxy, so any test whose git commands accidentally dial the network
	// fails fast instead of reaching it or prompting for credentials (regressions
	// #1463, 53bc37a88). The config lives in the file because GitIsolatedEnv strips
	// inherited GIT_CONFIG_* env; it proxies transport only (not url.insteadOf, which
	// would corrupt origin-URL forge detection) and leaves loopback servers untouched.
	isolation := map[string]string{
		"ENTIRE_CONFIG_DIR":           filepath.Join(tmpDir, "entire-config"),
		"XDG_CACHE_HOME":              filepath.Join(tmpDir, "entire-cache"),
		"ENTIRE_TOKEN_STORE":          "file",
		"ENTIRE_TOKEN_STORE_PATH":     filepath.Join(tmpDir, "entire-tokens.json"),
		"ENTIRE_TEST_AUTH_STORE_FILE": filepath.Join(tmpDir, "entire-auth-tokens.json"),
		"GIT_TERMINAL_PROMPT":         "0",
		testutil.EnvGitHermetic:       "1",
		// Plugin fixtures are file:// repos, which the shipped allowlist
		// refuses — nothing in production needs a local git remote, and a
		// security allowlist should not be widened for test convenience.
		// testing.Testing() is false in the spawned binary, so it is told here.
		"ENTIRE_TEST_ALLOW_FILE_REMOTES": "1",
	}
	for k, v := range isolation {
		if err := os.Setenv(k, v); err != nil {
			fmt.Fprintf(os.Stderr, "failed to set %s: %v\n", k, err)
			os.RemoveAll(tmpDir)
			os.Exit(1)
		}
	}

	moduleRoot := findModuleRoot()
	buildCmd := exec.CommandContext(context.Background(), "go", "build", "-o", testBinaryPath, ".")
	buildCmd.Dir = filepath.Join(moduleRoot, "cmd", "entire")

	buildOutput, err := buildCmd.CombinedOutput()
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to build CLI binary: %v\nOutput: %s\n", err, buildOutput)
		os.RemoveAll(tmpDir)
		os.Exit(1)
	}

	// Run tests
	code := m.Run()

	// Cleanup
	os.RemoveAll(tmpDir)
	os.Exit(code)
}
// which is distinct from IDLE + GitCommit → ActionCondense.
//
// Flow:
// 1. Agent creates files A and B, then stops (IDLE)
// 2. Session ends (ENDED via SimulateSessionEnd)
// 3. User commits file A → checkpoint #1
// 4. User commits file B → checkpoint #2
// 5. Both checkpoints exist, unique IDs, no shadow branches remain
func TestShadow_EndedSession_UserCommitsRemainingFiles(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t)

	sess := env.NewSession()

	// Start session (ACTIVE)
	if err := env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(sess.ID, "Create files A and B", sess.TranscriptPath); err != nil {
		t.Fatalf("user-prompt-submit failed: %v", err)
	}

	// Create files
	env.WriteFile("fileA.go", pkgFuncA)
	env.WriteFile("fileB.go", pkgFuncB)

	sess.CreateTranscript("Create files A and B", []FileChange{
		{Path: "fileA.go", Content: pkgFuncA},
		{Path: "fileB.go", Content: pkgFuncB},
	})

	// Stop session (IDLE)
	if err := env.SimulateStop(sess.ID, sess.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop failed: %v", err)
	}

	state, err := env.GetSessionState(sess.ID)
	if err != nil {
		t.Fatalf("GetSessionState failed: %v", err)
	}
	if state.Phase != session.PhaseIdle {
		t.Errorf("Expected IDLE phase, got %s", state.Phase)
	}

	// End session (ENDED) — exercises the distinct ENDED code path
	if err := env.SimulateSessionEnd(sess.ID); err != nil {
		t.Fatalf("SimulateSessionEnd failed: %v", err)
	}

	state, err = env.GetSessionState(sess.ID)
	if err != nil {
		t.Fatalf("GetSessionState failed: %v", err)
	}
	if state.Phase != session.PhaseEnded {
		t.Errorf("Expected ENDED phase, got %s", state.Phase)
	}
	if state.EndedAt == nil {
		t.Error("EndedAt should be set after session-end")
	}
	t.Logf("Session phase: %s, EndedAt: %v, FilesTouched: %v",
		state.Phase, state.EndedAt, state.FilesTouched)

	// User commits file A → checkpoint #1
	env.GitCommitWithShadowHooks("Add file A", "fileA.go")
	firstCommitHash := env.GetHeadHash()
	firstCheckpointID := env.GetCheckpointIDFromCommitMessage(firstCommitHash)
	if firstCheckpointID == "" {
		t.Fatal("First commit should have checkpoint trailer (ENDED session, files overlap)")
	}
	t.Logf("First checkpoint ID: %s", firstCheckpointID)

	// Verify phase stays ENDED
	state, err = env.GetSessionState(sess.ID)
	if err != nil {
		t.Fatalf("GetSessionState failed: %v", err)
	}
	if state.Phase != session.PhaseEnded {
		t.Errorf("Expected phase to stay ENDED after commit, got %s", state.Phase)
	}

	// Validate first checkpoint
	env.ValidateCheckpoint(CheckpointValidation{
		CheckpointID:    firstCheckpointID,
		SessionID:       sess.ID,
		FilesTouched:    []string{"fileA.go"},
		ExpectedPrompts: []string{"Create files A and B"},
	})

	// User commits file B → checkpoint #2
	env.GitCommitWithShadowHooks("Add file B", "fileB.go")
	secondCommitHash := env.GetHeadHash()
	secondCheckpointID := env.GetCheckpointIDFromCommitMessage(secondCommitHash)
	if secondCheckpointID == "" {
		t.Fatal("Second commit should have checkpoint trailer (carry-forward in ENDED)")
	}
	t.Logf("Second checkpoint ID: %s", secondCheckpointID)

	// Checkpoint IDs must be unique
	if firstCheckpointID == secondCheckpointID {
		t.Errorf("Each commit should get a unique checkpoint ID.\nFirst: %s\nSecond: %s",
			firstCheckpointID, secondCheckpointID)
	}

	// Validate second checkpoint
	env.ValidateCheckpoint(CheckpointValidation{
		CheckpointID:    secondCheckpointID,
		SessionID:       sess.ID,
		FilesTouched:    []string{"fileB.go"},
		ExpectedPrompts: []string{"Create files A and B"},
	})

	// No shadow branches should remain
	branchesAfter := env.ListBranchesWithPrefix("entire/")
	for _, b := range branchesAfter {
		if b != paths.MetadataBranchName && b != paths.TrailsBranchName {
			t.Errorf("Unexpected shadow branch after all files committed: %s", b)
		}
	}

	t.Log("EndedSession_UserCommitsRemainingFiles test completed successfully")
}

