	t.Helper()
	cmd := exec.CommandContext(t.Context(), "git", "show-ref", "--verify", "--quiet", ref)
	cmd.Dir = dir
	cmd.Env = testutil.GitIsolatedEnv()
	return cmd.Run() == nil
}

