func (env *TestEnv) GetSessionState(sessionID string) (*strategy.SessionState, error) {
	env.T.Helper()

	stateFile := filepath.Join(env.RepoDir, ".git", "entire-sessions", sessionID+".json")

	data, err := os.ReadFile(stateFile)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read session state: %w", err)
	}

	var state strategy.SessionState
	if err := json.Unmarshal(data, &state); err != nil {
		return nil, fmt.Errorf("failed to parse session state: %w", err)
	}
	return &state, nil
}

// WriteSessionState writes the session state for the given session ID.
// This is useful for tests that need to manipulate session state directly.
func (env *TestEnv) WriteSessionState(sessionID string, state *strategy.SessionState) error {
	env.T.Helper()

	stateDir := filepath.Join(env.RepoDir, ".git", "entire-sessions")
	if err := os.MkdirAll(stateDir, 0o755); err != nil {
		return fmt.Errorf("failed to create session state dir: %w", err)
	}

	stateFile := filepath.Join(stateDir, sessionID+".json")

	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal session state: %w", err)
	}

	if err := os.WriteFile(stateFile, data, 0o644); err != nil {
		return fmt.Errorf("failed to write session state: %w", err)
	}
	return nil
}

---
name: verify-fix
description: Verify that a bug fix addresses the original reproduced failure without relying on assumptions. Use when the user asks whether a fix worked or to verify a fix, and after changing code for a bug, especially when comparing before and after behavior.
user-invocable: true
disable-model-invocation: false
---

# Verify Fix

Prove the original failure no longer happens.

## Do

- Rerun the exact reproduction or regression test that failed before the fix through the
  production boundary that owns the behavior.
- Verify the outermost affected command, hook, request, or job result, not only a helper error.
- After cancellation or failure, perform the next real operation that would expose a leaked lock,
  child process, temporary file, goroutine, or partially written state.
- Poison relevant ambient environment variables when inherited process state could redirect the
  operation or hide the failure.
- For concurrency and subprocess fixes, use the real lock, process, protocol, and backend whenever
  they define the contract.
- Run the nearest broader test suite that could catch regressions.
- Compare before and after behavior using concrete outputs.
- If the check still fails, keep debugging instead of summarizing success.

## Output

```text
Verification
- Original failing check:
- Fixed result:
- Outermost workflow result:
- Aftermath check:
- Environment controls:
- Broader checks:
- Remaining risk:
```

